def __len__(self):
    if self.disable:
        # If tqdm is disabled, return the length of the iterable
        return len(self.iterable) if hasattr(self.iterable, "__len__") else float('inf')
    return self.total if self.iterable is None else \
        (self.iterable.shape[0] if hasattr(self.iterable, "shape")
         else len(self.iterable) if hasattr(self.iterable, "__len__")
         else self.total)
```

